from itertools import product

bbox = [[0,1,0],[1,0,1],[1,1,0]]

def rot(m):
    return [list(row) for row in zip(*m[::-1])]
def mir(m):
    return [row[::-1] for row in m]

tiles = {}
t = bbox
for i in range(4):
    tiles[f'rot{i}'] = t
    tiles[f'mir_rot{i}'] = mir(t)
    t = rot(t)

seed2 = [(10,13),(11,13),(11,14)]
seed3 = [(19,7),(19,9),(19,10),(20,8),(20,10),(21,7),(21,8),(21,10)]

def check(seed, tile, name):
    h, w = len(tile), len(tile[0])
    ones = {(r,c) for r in range(h) for c in range(w) if tile[r][c]}
    sols = []
    for r0 in range(h):
        for c0 in range(w):
            if all(((r-r0)%h, (c-c0)%w) in ones for r,c in seed):
                sols.append((r0,c0))
    if sols: print(name, sols)
    return sols

for name, tile in tiles.items():
    check(seed2, tile, 'rect2 '+name)
    check(seed3, tile, 'rect3 '+name)

